Reprodutibilidade
Todo o site é gerado por um pipeline em R (targets) que roda mensalmente no GitHub Actions: consulta as fontes, recalcula os indicadores, regenera as páginas das cadeias e publica. Cuidados técnicos tratados no código:

colunas da RAIS armazenadas como texto (SAFE_CAST), contagens em integer64 convertidas;
CNAE sempre como texto de 5 dígitos, para não perder zeros à esquerda;
conferência automática do esquema das tabelas antes de extrair, com erro explícito se uma coluna mudar de nome.

Setores: agregar e desagregar
Escolha o nível da classificação (do grande setor à classe CNAE) e o recorte. A tabela mostra o emprego formal e a variação em 10 e 5 anos; clique em um nome para abrir o nível de baixo.


Código
setb = FileAttachment("dados/setores.json").json()
NIVEIS = [["grande", null, "Grande setor"], ["secao", "descricao_secao", "Seção"], ["divisao", "descricao_divisao", "Divisão"],
          ["grupo", "descricao_grupo", "Grupo"], ["classe", "descricao_classe", "Classe"]]
recortes = ["Pernambuco", ...Array.from(new Set(setb.dados.map(d =&gt; d.rd))).filter(d =&gt; d !== "Pernambuco").sort()]
viewof nivelSet = Inputs.radio(new Map(NIVEIS.map(n =&gt; [n[2], n[0]])), {label: "Nível", value: "secao"})
viewof recSet = Inputs.select(recortes, {label: "Recorte", value: "Pernambuco"})
mutable filtroSet = null
dicSet = new Map(setb.dicionario.map(d =&gt; [d.classe, d]))
tabSet = {
  const [a0, a5, a1] = setb.anos;
  const nv = NIVEIS.find(n =&gt; n[0] === nivelSet);
  const pai = filtroSet;
  const agg = new Map();
  for (const d of setb.dados) {
    if (d.rd !== recSet) continue;
    const c = dicSet.get(d.classe); if (!c) continue;
    if (pai && c[pai.nivel] !== pai.codigo) continue;
    const chave = c[nivelSet];
    const nome = nv[1] ? c[nv[1]] : chave;
    if (!agg.has(chave)) agg.set(chave, {codigo: chave, nome, e0: 0, e5: 0, e1: 0, estab: 0});
    const o = agg.get(chave);
    if (d.ano === a0) o.e0 += d.emprego; if (d.ano === a5) o.e5 += d.emprego;
    if (d.ano === a1) { o.e1 += d.emprego; o.estab += d.estab; }
  }
  const tot = d3.sum(agg.values(), d =&gt; d.e1);
  return Array.from(agg.values()).map(o =&gt; ({...o, part: o.e1 / tot, v10: o.e0 &gt; 0 ? o.e1 / o.e0 - 1 : null, v5: o.e5 &gt; 0 ? o.e1 / o.e5 - 1 : null}))
    .sort((a, b) =&gt; b.e1 - a.e1);
}
nfS = (x, d = 0) =&gt; x == null || isNaN(x) ? "–" : x.toLocaleString("pt-BR", {maximumFractionDigits: d, minimumFractionDigits: d})
pS = x =&gt; x == null || !isFinite(x) ? "–" : (x &gt; 0 ? "+" : "") + (100 * x).toLocaleString("pt-BR", {maximumFractionDigits: 1}) + "%"
{
  const prox = {grande: "secao", secao: "divisao", divisao: "grupo", grupo: "classe"}[nivelSet];
  const nomeNivel = NIVEIS.find(n =&gt; n[0] === nivelSet)[2];
  const el = html`&lt;div&gt;
    ${filtroSet ? html`&lt;p class="aviso"&gt;Mostrando só o que está dentro de &lt;b&gt;${filtroSet.nome}&lt;/b&gt;. &lt;a href="#setores" class="set-limpar"&gt;Ver tudo&lt;/a&gt;&lt;/p&gt;` : ""}
    &lt;table class="rx-tab"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;${nomeNivel}&lt;/th&gt;&lt;th&gt;Empregos ${setb.anos[2]}&lt;/th&gt;&lt;th&gt;% do recorte&lt;/th&gt;&lt;th&gt;Em 10 anos&lt;/th&gt;&lt;th&gt;Em 5 anos&lt;/th&gt;&lt;th&gt;Estab.&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${tabSet.slice(0, 60).map(d =&gt; html`&lt;tr&gt;
      &lt;td&gt;${prox ? html`&lt;a href="#setores" class="set-abrir" data-cod="${d.codigo}" data-nome="${d.nome}"&gt;${d.nome}&lt;/a&gt;` : d.nome}&lt;/td&gt;
      &lt;td&gt;${nfS(d.e1)}&lt;/td&gt;&lt;td&gt;${nfS(100 * d.part, 1)}%&lt;/td&gt;&lt;td&gt;${pS(d.v10)}&lt;/td&gt;&lt;td&gt;${pS(d.v5)}&lt;/td&gt;&lt;td&gt;${nfS(d.estab)}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;
    ${tabSet.length &gt; 60 ? html`&lt;p class="fonte"&gt;Mostrando as 60 maiores de ${tabSet.length}.&lt;/p&gt;` : ""}&lt;/div&gt;`;
  el.querySelectorAll("a.set-abrir").forEach(a =&gt; a.addEventListener("click", e =&gt; {
    e.preventDefault();
    mutable filtroSet = {nivel: nivelSet, codigo: a.dataset.cod, nome: a.dataset.nome};
    viewof nivelSet.value = prox;
    viewof nivelSet.dispatchEvent(new Event("input", {bubbles: true}));
  }));
  const l = el.querySelector("a.set-limpar");
  if (l) l.addEventListener("click", e =&gt; { e.preventDefault(); mutable filtroSet = null; });
  return el;
}
















































































